function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is an integer between 1 and 10^9.';
  const count = new Map();
  for (const v of nums) count.set(v, (count.get(v) || 0) + 1);
  for (const times of count.values()) if (times * 2 > nums.length) return null;
  return 'nums must have a dominant value: one that fills more than half of it.';
}

