function minimumIndex(nums) {
  const count = new Map();
  for (const value of nums) {
    count.set(value, (count.get(value) || 0) + 1);
  }

  let dominant = nums[0];
  for (const [value, freq] of count) {
    if (freq > count.get(dominant)) {
      dominant = value;
    }
  }

  const total = count.get(dominant);
  let leftCount = 0;
  for (let i = 0; i < nums.length - 1; i++) {
    if (nums[i] === dominant) {
      leftCount++;
    }
    const rightCount = total - leftCount;
    const leftSize = i + 1;
    const rightSize = nums.length - leftSize;
    if (leftCount * 2 > leftSize && rightCount * 2 > rightSize) {
      return i;
    }
  }
  return -1;
}

