function minimumIndex(nums) {
  // Find each part's dominant value from scratch for every split.
  const dominantOf = (part) => {
    for (const candidate of part) {
      let times = 0;
      for (const v of part) if (v === candidate) times++;
      if (times * 2 > part.length) return candidate;
    }
    return null;
  };
  for (let i = 0; i + 1 < nums.length; i++) {
    const first = dominantOf(nums.slice(0, i + 1));
    const second = dominantOf(nums.slice(i + 1));
    if (first !== null && first === second) return i;
  }
  return -1;
}

