function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const limit = size === 'large' ? 1000000000 : 6;
  const dominant = 1 + Math.floor(rand() * limit);
  const least = Math.floor(n / 2) + 1;
  // Often barely dominant, so that many splits fail.
  const times = rand() < 0.6 ? Math.min(n, least + Math.floor(rand() * 3)) : least + Math.floor(rand() * (n - least + 1));
  const nums = [];
  for (let k = 0; k < times; k++) nums.push(dominant);
  while (nums.length < n) {
    const other = 1 + Math.floor(rand() * limit);
    if (other !== dominant) nums.push(other);
  }
  const shape = rand();
  if (shape < 0.6) {
    for (let k = n - 1; k > 0; k--) {
      const r = Math.floor(rand() * (k + 1));
      [nums[k], nums[r]] = [nums[r], nums[k]];
    }
  } else if (shape < 0.8) {
    nums.reverse();
  } else {
    // Others first, then the dominant copies, with a few random swaps.
    nums.reverse();
    const others = nums.filter(v => v !== dominant);
    nums.splice(0, n, ...others, ...new Array(times).fill(dominant));
    for (let s = 0; s < 3; s++) {
      const a = Math.floor(rand() * n);
      const b = Math.floor(rand() * n);
      [nums[a], nums[b]] = [nums[b], nums[a]];
    }
  }
  return [nums];
}
